code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = []
    seen = set()
    for r in range(h-2):
        for c in range(w-2):
            color = grid[r][c]
            if color and all(grid[i][j] == color for i in range(r,r+3) for j in range(c,c+3)):
                if (r,c,color) not in seen:
                    blocks.append((r+1,c+1,color))
                    seen.add((r,c,color))
    out = [row[:] for row in grid]
    lines = [[set() for _ in range(w)] for _ in range(h)]
    for r,c,color in blocks:
        for j in range(w): lines[r][j].add(color)
        for i in range(h): lines[i][c].add(color)
    for i in range(h):
        for j in range(w):
            if len(lines[i][j]) == 1: out[i][j] = next(iter(lines[i][j]))
            elif len(lines[i][j]) > 1: out[i][j] = 0
    return out
'''
